    void setLastHoveredNode(NodeId const nodeId);

    NodeId lastHoveredNode() const;

    void resetLastHoveredNode();

private:
    ConnectionGraphicsObject &_cgo;

    bool _hovered;

    NodeId _lastHoveredNode{InvalidNodeId};
};

