import json, random, string
from typing import List

# Target format: JSON text consumed by QtNodes style loaders.
# We generate small, valid JSON objects exercising diverse keys and value types
# expected by ConnectionStyle, NodeStyle, and GraphicsViewStyle.

_MAX_BYTES = 4096

_color_names = [
    "red","green","blue","cyan","magenta","yellow","black","white",
    "gray","darkGray","lightGray","transparent"
]

def _hex_color(r: int, g: int, b: int, a: int | None = None) -> str:
    if a is None:
        return f"#{r:02x}{g:02x}{b:02x}"
    return f"#{r:02x}{g:02x}{b:02x}{a:02x}"


def _rand_color_str(rng: random.Random) -> str:
    which = rng.randrange(0, 4)
    if which == 0:
        # full hex
        return _hex_color(rng.randrange(256), rng.randrange(256), rng.randrange(256))
    if which == 1:
        # hex with alpha
        return _hex_color(rng.randrange(256), rng.randrange(256), rng.randrange(256), rng.randrange(256))
    if which == 2:
        # rgb() css-like
        return f"rgb({rng.randrange(256)},{rng.randrange(256)},{rng.randrange(256)})"
    # named color
    return rng.choice(_color_names)


def _rand_bool(rng: random.Random) -> bool:
    return bool(rng.getrandbits(1))


def _rand_float(rng: random.Random, lo: float, hi: float) -> float:
    return rng.random() * (hi - lo) + lo


def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p


def _style_connection(rng: random.Random) -> dict:
    # Keys commonly used by ConnectionStyle
    obj = {
        "ConstructionColor": _rand_color_str(rng),
        "NormalColor": _rand_color_str(rng),
        "SelectedColor": _rand_color_str(rng),
        "SelectedHaloColor": _rand_color_str(rng),
        "HoveredColor": _rand_color_str(rng),
        "LineWidth": round(_rand_float(rng, 0.1, 30.0), 3),
        "ConstructionLineWidth": round(_rand_float(rng, 0.1, 30.0), 3),
        "PointDiameter": round(_rand_float(rng, 0.5, 40.0), 3),
        "UseDataDefinedColors": _rand_bool(rng),
    }
    # Also add type-specific normal colors map variant sometimes
    if _maybe(rng, 0.5):
        type_map = {}
        for _ in range(rng.randrange(1, 5)):
            key = "type_" + ''.join(rng.choice(string.ascii_letters) for _ in range(rng.randrange(3, 8)))
            type_map[key] = _rand_color_str(rng)
        obj["NormalColorByType"] = type_map
    return obj


def _style_node(rng: random.Random) -> dict:
    # Keys for NodeStyle
    obj = {
        "NormalBoundaryColor": _rand_color_str(rng),
        "SelectedBoundaryColor": _rand_color_str(rng),
        "GradientColor0": _rand_color_str(rng),
        "GradientColor1": _rand_color_str(rng),
        "GradientColor2": _rand_color_str(rng),
        "GradientColor3": _rand_color_str(rng),
        "ShadowColor": _rand_color_str(rng),
        "ShadowEnabled": _rand_bool(rng),
        "FontColor": _rand_color_str(rng),
        "FontColorFaded": _rand_color_str(rng),
        "ConnectionPointColor": _rand_color_str(rng),
        "FilledConnectionPointColor": _rand_color_str(rng),
        "WarningColor": _rand_color_str(rng),
        "ErrorColor": _rand_color_str(rng),
        "ToolTipIconColor": _rand_color_str(rng),
        "PenWidth": round(_rand_float(rng, 0.1, 10.0), 3),
        "HoveredPenWidth": round(_rand_float(rng, 0.1, 10.0), 3),
        "ConnectionPointDiameter": round(_rand_float(rng, 1.0, 40.0), 3),
        "Opacity": round(_rand_float(rng, 0.1, 1.0), 3),
    }
    # Optionally include processing icon style
    if _maybe(rng, 0.5):
        obj["ProcessingIconStyle"] = {
            "pos": rng.choice(["BottomLeft", "BottomRight", 0, 1]),
            "size": round(_rand_float(rng, 8.0, 64.0), 3),
            "margin": round(_rand_float(rng, 0.0, 24.0), 3),
            "resolution": rng.randrange(16, 256, 8),
        }
    # Optionally override background color helper
    if _maybe(rng, 0.5):
        obj["BackgroundColor"] = _rand_color_str(rng)
    return obj


def _style_view(rng: random.Random) -> dict:
    # Keys for GraphicsViewStyle
    return {
        "BackgroundColor": _rand_color_str(rng),
        "FineGridColor": _rand_color_str(rng),
        "CoarseGridColor": _rand_color_str(rng),
    }


def _merge_dicts(dicts: List[dict]) -> dict:
    out: dict = {}
    for d in dicts:
        out.update(d)
    return out


def _top_level(rng: random.Random) -> dict:
    # Build a composite object that can feed any of the setStyle/loadJson consumers.
    parts = []
    # Always include at least one section strongly relevant to each style type
    parts.append(_style_connection(rng))
    parts.append(_style_node(rng))
    parts.append(_style_view(rng))

    # Add some innocuous extras to exercise unknown-key handling
    if _maybe(rng, 0.6):
        parts.append({
            "meta": {
                "theme": rng.choice(["light", "dark", "system"]),
                "comment": "generated test style",
                "version": f"{rng.randrange(0,5)}.{rng.randrange(0,10)}.{rng.randrange(0,10)}",
            }
        })
    # Optional nested alternate schemas to test robustness
    if _maybe(rng, 0.3):
        parts.append({
            "palettes": [
                {"name": "warm", "colors": [_rand_color_str(rng) for _ in range(rng.randrange(3,8))]},
                {"name": "cool", "colors": [_rand_color_str(rng) for _ in range(rng.randrange(3,8))]},
            ]
        })
    return _merge_dicts(parts)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Randomly decide to produce either a compact object or wrap it in a trivial envelope
    obj = _top_level(rng)

    # With some probability, shuffle some numeric types between int/float to
    # exercise QVariant conversions while staying valid JSON.
    for key in list(obj.keys()):
        val = obj[key]
        if isinstance(val, float) and _maybe(rng, 0.3):
            # Convert to int-like when close to integer
            obj[key] = int(val)
        elif isinstance(val, (int, float)) and _maybe(rng, 0.2):
            # Box inside a small object the loaders will likely ignore
            obj[key] = {"value": val}

    # Serialize deterministically (seeded randomness already chosen content)
    text = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    data = text.encode("utf-8")
    if len(data) > _MAX_BYTES:
        # Truncate safely at a boundary by re-serializing a pruned object
        # Keep only a subset of keys to stay valid JSON
        keys = list(obj.keys())
        rng.shuffle(keys)
        pruned = {}
        total = 0
        for k in keys:
            pruned[k] = obj[k]
            s = json.dumps(pruned, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            if len(s) > _MAX_BYTES:
                del pruned[k]
                break
            total = len(s)
        data = json.dumps(pruned, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return data
